  const subset = Object.keys(groups).slice(0, i).map(key => groups[key]);
  if (subset.reduce((sum, val) => sum + val, 0) >= threshold) {
    const isMinimalWinning = subset.every((val, idx, arr) => 
      arr.slice(0, idx).reduce((sum, val) => sum + val, 0) + val + arr.slice(idx + 1).reduce((sum, val) => sum + val, 0) >= threshold
    );
